describe('AuthPage Tests', function () {
    beforeEach(function () {
        cy.intercept('POST', '/api/authenticate', function (req) {
            var urlParams = new URLSearchParams(req.body);
            var token = urlParams.get('token');
            if (token === 'valid-token') {
                req.reply({ status: 'ok', credentials: 'valid-token', language: 'en' });
            }
            else {
                req.reply({ status: 'error' });
            }
        });
    });
    it('Redirects to login if no token is provided', function () {
        cy.visit('http://localhost:3000/auth');
        cy.url().should('include', '/');
    });
    it('Authenticates successfully with a valid token', function () {
        cy.visit('http://localhost:3000/auth?dvgnqw40d8a/T1T2pkVS783/WsEzxI8EMtP6W0Qjl/ykpFK8kc4bN2eTYilfQNMGaTkFtQNhCma0mm4oqw3CRw==');
        cy.wait(1000);
        cy.url().should('include', '/chat');
    });
    it('Redirects to login if authentication fails', function () {
        cy.visit('http://localhost:3000/auth?dvgnqw40d8a/T1T2pktP6W0Qjl/ykpFK8kc4bN2eTYilfQNMGaTkFtQNhCma0mm4oqw3CRw==');
        cy.wait(1000);
        cy.url().should('include', '/');
    });
    it('Displays the authentication message', function () {
        cy.visit('http://localhost:3000/auth?token=valid-token');
        cy.contains('Authenticating...');
    });
    it("login user with using the form", function () {
        cy.visit('http://localhost:3000/auth');
        cy.get('.w-full.p-2.border-gray-300').first().type('ADM');
        cy.get('.flex > :nth-child(2) > .w-full').type('Hammashuolto1!');
        cy.get('button[type="submit"]').click();
        cy.contains('Authenticating...');
    });
});
